package cn.zhuatech.recruitai.service; import jakarta.validation.constraints.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class CandidateMatchService { public record Request(@NotBlank String candidate,@NotBlank String jobTitle,@NotEmpty List<String> requiredSkills,@NotEmpty List<String> candidateSkills,@Min(0) int years){} public record Result(String candidate,String jobTitle,int score,List<String> matched,List<String> gaps,String recommendation){} public Result match(Request r){var have=new HashSet<>(r.candidateSkills().stream().map(String::toLowerCase).toList());var matched=r.requiredSkills().stream().filter(x->have.contains(x.toLowerCase())).toList();var gaps=r.requiredSkills().stream().filter(x->!have.contains(x.toLowerCase())).toList();int score=Math.min(100,matched.size()*70/Math.max(1,r.requiredSkills().size())+Math.min(30,r.years()*5));return new Result(r.candidate(),r.jobTitle(),score,matched,gaps,score>=75?"优先进入人工面试":"由招聘顾问复核，不自动淘汰");} }
